head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name getCookie
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getCookie = function(Name) {
    var search = Name + "=";
    if (document.cookie.length > 0) {
        // 쿠키가 설정되어 있다면
        offset = document.cookie.indexOf(search);
        if (offset != -1) {
            // 쿠키가 존재하면
            offset += search.length; // set index of beginning of value
            end = document.cookie.indexOf(";", offset); // 쿠키 값의 마지막 위치 인덱스 번호 설정
            if (end == -1) end = document.cookie.length;
            return unescape(document.cookie.substring(offset, end));
        }
    }
    return "";
};


/*
 * 상장업무처리 메세지 처리
 */
LastJob = "";
/**
 * @method
 * @name fn_isProcess
 * @description desc
 * @param {string} gubun desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isProcess = function(gubun) {
    if (gubun == 'I') scwin.LastJob = '저장';

    else if (gubun == 'U') scwin.LastJob = '수정';

    else if (gubun == 'D') scwin.LastJob = '삭제';

    else if (gubun == 'S') scwin.LastJob = '제출';
    var listBzCd = $("[name='listBzCd']").val();
    if (gubun == 'S' && listBzCd == '0') {
        //손실제한ETN - 상장예비심사청구에서 제출버튼 클릭시만 체크

        if (scwin.fn_procsBefIdxEarCheck()) {
            return;
        }
    }
    if (!window.confirm("[" + scwin.LastJob + "] 하시겠습니까?")) {
        return false;
    }
    return true;
};


//제출 전 다시 한번 체크사항
//발행증권에 관한 사항 - 기초지수명과 발행증권에 관한 사항2(손실제한) - 수익구조유형에 조기상환 종류 선택 체크(2019-07-26 운영반영)
/**
 * @method
 * @name fn_procsBefIdxEarCheck
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_procsBefIdxEarCheck = function() {
    var r = false;
    var lastChkData = document.etnListForm.lastChkData.getValue();
    var bzProcsNo = document.etnListForm.bzProcsNo.getValue(); //상세보기에서 가져오는 업무처리번호
    var checkSub = document.etnListForm.checkSub; //목록에서 가져오는 업무처리번호(다중)

    if (typeof checkSub == 'object') {
        var cnt = 0;
        for (var i = 0; i < checkSub.length; i++) {
            if (checkSub[i].checked == true) {
                if (cnt > 0) {
                    lastChkData += ',';
                }
                lastChkData += checkSub[i].getValue();
                cnt++;
            }
        }
    } else {
        lastChkData = bzProcsNo;
    }
    $.ajax({
        type: "POST",
        url: "/etn/ajaxIdxCdEarlyRedmptCheck.do",
        async: false,
        data: {
            method: "ajaxProcsBefIdxEarCheck",
            lastChkData: lastChkData
        },
        success: function(data) {
            result = $.parseJSON(data);
            if (result.val != '' && result.val != null) {
                //데이터가 있으면

                var alet = '발행증권에 관한 사항 - 기초지수명이 코스피, 코스피200, 코스닥, 코스닥150, KTOP 30, 코스피 양매도 5% OTM지수, KRX 금현물지수인 경우만 조기상환을 선택할 수 있습니다.' + '\n발행증권에 관한 사항2(손실제한) - 수익구조유형을 변경하고 진행해주세요.';
                if (typeof checkSub == 'object') {
                    alet += '\n\n종목코드 : ' + result.val;
                }
                alert(alet);
                lastChkData = '';
                r = true;
            }
        },
        error: function(request, status, error) {
            alert("제출시 체크에 실패하였습니다.");
            return;
        },
        complete: function() {

        }
    });
    return r;
};


/* ETN신청 다중제출 */
/**
 * @method
 * @name fn_EtnSelectSub
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EtnSelectSub = function() {
    if (!$("[name='checkSub']").is(':checked')) {
        alert('선택된 항목이 없습니다.');
        return;
    }
    if (!scwin.fn_isProcess('S')) return;
    form = document.etnListForm;
    form.action = '/etn/LossLimitEtnList.do';
    form.method.setValue('lossLimitSubmitMultiList');
    form.submit();
};


/* ETN 엑셀 템플릿 다운로드*/
/**
 * @method
 * @name fn_EtnExcelDownload
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EtnExcelDownload = function() {
    form = document.etnListForm;
    form.action = '/etn/LossLimitEtnList.do';
    form.method.setValue('lossLimitEtnExcelDownload');
    form.submit();
};


/* 손실제한 ETN 엑셀 파일 업로드 팝업 이동*/
/**
 * @method
 * @name fn_EtnExcelUploadPop
 * @description desc
 * @param {string} listBzCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EtnExcelUploadPop = function(listBzCd) {
    var i = 0;
    i++;
    var popName = "pop_excelUpload_" + i;
    var urlLink = "";
    if (scwin.getCookie(popName) != popName) {
        if (listBzCd == 0) {
            urlLink = "/etn/JLDFIL70811.jsp";
        } else if (listBzCd == 1) {
            urlLink = "/etn/JLDFIL70911.jsp";
        } else if (listBzCd == 2) {
            urlLink = "/etn/JLDFIL71011.jsp";
        } else if (listBzCd == 3) {
            urlLink = "/etn/JLDFIL71111.jsp";
        }
        window.open(urlLink, popName, "scrollbars=no,toolbar=no,resizable=yes,width=500,height=500,left=0,top=0");
    }
};



/* 선택제출 체크박스 전체선택/전체해제*/
$(document).ready(function() {
    $("#checkAll").click(function() {
        if ($(this).is(":checked")) {
            $("input:checkbox[name='checkSub']").attr("checked", true);
        } else {
            $("input:checkbox[name='checkSub']").attr("checked", false);
        }
    });
});
